type Customer =
  | { kind: "known"; name: string; balance: number }
  | { kind: "unknown" };                     // the special case, no payload

export const unknown: Customer = Object.freeze({ kind: "unknown" });

function displayName(c: Customer): string {
  switch (c.kind) {
    case "known":   return c.name;
    case "unknown": return "occupant";       // assertNever(default) in real code
  }
}
